352	     1	package sk.knizat.tennisclub.service;
353	     2	
354	     3	import lombok.AccessLevel;
355	     4	import lombok.NoArgsConstructor;
356	     5	import sk.knizat.tennisclub.exception.ValidationException;
357	     6	
358	     7	import java.util.regex.Pattern;
359	     8	
360	     9	/**
361	    10	 * Phone number normalisation (ARCHITECTURE.md O-14).
362	    11	 * <p>
363	    12	 * Validation is two-staged: DTOs accept a loose form via Bean Validation (digits, optional {@code +},
364	    13	 * spaces and hyphens), and {@link #normalise(String)} then removes all whitespace and hyphens and checks
365	    14	 * the strict form {@value #STRICT_PATTERN}. The normalised value is what gets stored, compared and used as
366	    15	 * login, so {@code "+421 900 000 001"} and {@code "+421900000001"} are the same customer, while
367	    16	 * {@code "+421..."} and {@code "421..."} are two different ones (no prefix completion).
368	    17	 */
369	    18	@NoArgsConstructor(access = AccessLevel.PRIVATE)
370	    19	public final class PhoneNumbers {
371	    20	
372	    21	    /** Strict form of a normalised phone number: optional plus followed by 7 to 15 digits. */
373	    22	    public static final String STRICT_PATTERN = "^\\+?[0-9]{7,15}$";
374	    23	
375	    24	    private static final Pattern STRICT = Pattern.compile(STRICT_PATTERN);
376	    25	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-]+");
377	    26	
378	    27	    /**
379	    28	     * Strips whitespace and hyphens and validates the result.
380	    29	     *
381	    30	     * @param raw phone number as received from the client
382	    31	     * @return normalised phone number
383	    32	     * @throws ValidationException when the normalised value does not match {@value #STRICT_PATTERN}
384	    33	     */
385	    34	    public static String normalise(String raw) {
386	    35	        if (raw == null) {
387	    36	            throw new ValidationException("phoneNumber must not be null");
388	    37	        }
389	    38	        String normalised = SEPARATORS.matcher(raw).replaceAll("");
390	    39	        if (!STRICT.matcher(normalised).matches()) {
391	    40	            throw new ValidationException(
392	    41	                    "phoneNumber '" + raw + "' is not a valid phone number (expected " + STRICT_PATTERN
393	    42	                            + " after removing spaces and hyphens)");
394	    43	        }
395	    44	        return normalised;
396	    45	    }
397	    46	}
