401	     3	import org.springframework.stereotype.Component;
402	     4	import sk.knizat.tennisclub.entity.GameType;
403	     5	
404	     6	import java.math.BigDecimal;
405	     7	import java.math.RoundingMode;
406	     8	import java.time.Duration;
407	     9	import java.time.Instant;
408	    10	
409	    11	/**
410	    12	 * Stateless reservation price calculator: {@code whole minutes x pricePerMinute x (1.5 for doubles)},
411	    13	 * rounded {@code HALF_UP} to scale 2. Interval validity (positive length, whole minutes) is the caller's job.
412	    14	 */
413	    15	@Component
414	    16	public class PriceCalculator {
415	    17	
416	    18	    /** Multiplier applied to the price of a doubles game. */
417	    19	    public static final BigDecimal DOUBLES_MULTIPLIER = new BigDecimal("1.5");
418	    20	
419	    21	    /**
420	    22	     * Computes the price of the interval {@code [start, end)}.
421	    23	     *
422	    24	     * @param start          start of the reservation
423	    25	     * @param end            end of the reservation
424	    26	     * @param pricePerMinute price per minute of the court surface
425	    27	     * @param gameType       singles or doubles
426	    28	     * @return price with scale 2
427	    29	     */
428	    30	    public BigDecimal calculate(Instant start, Instant end, BigDecimal pricePerMinute, GameType gameType) {
429	    31	        long minutes = Duration.between(start, end).toMinutes();
430	    32	        BigDecimal price = pricePerMinute.multiply(BigDecimal.valueOf(minutes));
431	    33	        if (gameType == GameType.DOUBLES) {
432	    34	            price = price.multiply(DOUBLES_MULTIPLIER);
433	    35	        }
434	    36	        return price.setScale(2, RoundingMode.HALF_UP);
435	    37	    }
436	    38	}
