106	   106	     * <p>
107	   107	     * Only {@code r.deleted} is filtered on purpose: the court is matched by number regardless of its own
108	   108	     * deleted flag, so reservations made on a since-removed court remain listable.
109	   109	     */
110	   110	    @Override
111	   111	    public List<Reservation> findByCourtNumberOrderByCreatedAt(Integer courtNumber) {
112	   112	        return em.createQuery(SELECT_GRAPH
113	   113	                        + "WHERE c.courtNumber = :courtNumber AND r.deleted = false "
114	   114	                        + "ORDER BY r.createdAt ASC, r.id ASC", Reservation.class)
115	   115	                .setParameter("courtNumber", courtNumber)
116	   116	                .getResultList();
117	   117	    }
