119	   119	    /** {@inheritDoc} Overridden so that the lazy court/user graph is fetched like in the other list queries. */
120	   120	    @Override
121	   121	    public List<Reservation> findAll() {
122	   122	        return em.createQuery(SELECT_GRAPH + "WHERE r.deleted = false ORDER BY r.id", Reservation.class)
123	   123	                .getResultList();
124	   124	    }
