126	   126	    @Override
127	   127	    public List<Reservation> findByPhoneNumber(String phoneNumber, boolean futureOnly, Instant now) {
128	   128	        Objects.requireNonNull(phoneNumber, "phoneNumber");
129	   129	        if (futureOnly) {
130	   130	            Objects.requireNonNull(now, "now");
131	   131	        }
132	   132	        StringBuilder jpql = new StringBuilder(SELECT_GRAPH)
133	   133	                .append("WHERE u.phoneNumber = :phoneNumber AND u.deleted = false AND r.deleted = false ");
134	   134	        if (futureOnly) {
135	   135	            jpql.append("AND r.startTime > :now ");
136	   136	        }
137	   137	        jpql.append("ORDER BY r.startTime ASC, r.id ASC");
138	   138	        TypedQuery<Reservation> query = em.createQuery(jpql.toString(), Reservation.class)
139	   139	                .setParameter("phoneNumber", phoneNumber);
140	   140	        if (futureOnly) {
141	   141	            query.setParameter("now", now);
142	   142	        }
143	   143	        return query.getResultList();
144	   144	    }
