155	   155	        Objects.requireNonNull(courtId, "courtId");
156	   156	        Objects.requireNonNull(start, "start");
157	   157	        Objects.requireNonNull(end, "end");
158	   158	        StringBuilder jpql = new StringBuilder(
159	   159	                "SELECT COUNT(r) FROM Reservation r WHERE r.court.id = :courtId AND r.deleted = false "
160	   160	                        + "AND r.startTime < :end AND r.endTime > :start ");
161	   161	        if (excludeReservationId != null) {
162	   162	            jpql.append("AND r.id <> :excludeId");
