165	   165	                .setParameter("courtId", courtId)
166	   166	                .setParameter("start", start)
167	   167	                .setParameter("end", end);
168	   168	        if (excludeReservationId != null) {
169	   169	            query.setParameter("excludeId", excludeReservationId);
170	   170	        }
171	   171	        return exists(query);
172	   172	    }
